class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        groups = []

        for s in strs:
            placed = False
            for group in groups:
                if sorted(s) == sorted(group[0]):
                    group.append(s)
                    placed = True
                    break
            if not placed:
                groups.append([s])

        return groups
